//! Modbus TCP transport.
//!
//! Two wire formats are supported (P2-06/P2-08 follow-up):
//!
//! - `Mbap` (standard Modbus TCP): `[tx id (2)][protocol=0 (2)][length (2)][unit id (1)][PDU]`
//! - `Rtu` (RTU over TCP, common with serial gateways): raw RTU ADU incl. CRC.
//!
//! Transaction ids are generated by the scanner and echoed by the server;
//! the scanner validates them in `verify_adu`.

use ts_rs::TS;
use std::time::Duration;

use async_trait::async_trait;
use rustls::pki_types::ServerName;
use serde::{Deserialize, Serialize};
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};
use tokio::net::TcpStream;
use tokio_rustls::TlsConnector;

use super::tls::{build_client_config, TlsParams};
use super::{Transport, TransportError, TransportResult};

/// Wire format used on a TCP connection.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
pub enum TcpFraming {
    /// Standard MBAP-framed Modbus TCP.
    Mbap,
    /// Raw RTU ADU (unit id + PDU + CRC-16) carried by TCP.
    Rtu,
}

impl Default for TcpFraming {
    fn default() -> Self {
        Self::Mbap
    }
}

/// TCP connection parameters.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct TcpConfig {
    pub host: String,
    /// Modbus TCP default port 502; some devices use 503, 1502, 802...
    pub port: u16,
    /// TCP connect timeout.
    pub connect_timeout: Duration,
    /// Wire format (MBAP by default).
    #[serde(default)]
    pub framing: TcpFraming,
    /// Modbus Security: wrap the connection in TLS (standard port 802).
    #[serde(default)]
    pub tls: Option<TlsParams>,
}

impl Default for TcpConfig {
    fn default() -> Self {
        Self {
            host: "127.0.0.1".into(),
            port: 502,
            connect_timeout: Duration::from_millis(2000),
            framing: TcpFraming::Mbap,
            tls: None,
        }
    }
}

/// Combined stream trait so plain and TLS streams share one boxed type.
pub trait AsyncStream: AsyncRead + AsyncWrite + Send + Unpin {}
impl<T: AsyncRead + AsyncWrite + Send + Unpin> AsyncStream for T {}

/// Modbus TCP client transport.
pub struct TcpTransport {
    config: TcpConfig,
    stream: Box<dyn AsyncStream>,
}

impl TcpTransport {
    /// Connect to a Modbus TCP server.
    pub async fn connect(config: TcpConfig) -> TransportResult<Self> {
        let addr = format!("{}:{}", config.host, config.port);
        let stream = match tokio::time::timeout(config.connect_timeout, TcpStream::connect(&addr)).await {
            Ok(res) => res?,
            Err(_) => return Err(TransportError::Timeout(config.connect_timeout)),
        };
        // TCP_NODELAY: important for low-latency scanning.
        stream.set_nodelay(true)?;

        let stream: Box<dyn AsyncStream> = match &config.tls {
            Some(tls) => {
                let client_config = build_client_config(tls).map_err(TransportError::Other)?;
                let domain = ServerName::try_from(config.host.clone())
                    .map_err(|e| TransportError::Other(format!("invalid TLS server name: {e}")))?;
                let tls_stream = TlsConnector::from(client_config)
                    .connect(domain, stream)
                    .await
                    .map_err(TransportError::Io)?;
                Box::new(tls_stream)
            }
            None => Box::new(stream),
        };
        Ok(Self { config, stream })
    }

    /// Read one full MBAP-framed response.
    async fn read_mbap(&mut self) -> TransportResult<Vec<u8>> {
        let mut header = [0u8; 7];
        self.stream.read_exact(&mut header).await?;

        let protocol_id = u16::from_be_bytes([header[2], header[3]]);
        let length = u16::from_be_bytes([header[4], header[5]]);
        if protocol_id != 0 {
            return Err(TransportError::Other(format!("bad protocol id {protocol_id}")));
        }
        if !(1..=254).contains(&length) {
            return Err(TransportError::Other(format!("bad mbap length {length}")));
        }

        let mut rest = vec![0u8; length as usize];
        self.stream.read_exact(&mut rest).await?;
        let mut frame = header.to_vec();
        frame.extend_from_slice(&rest);
        Ok(frame)
    }

    /// Read a raw RTU frame: the stream is chunk-oriented, so use a short
    /// silence interval to decide that the frame is complete.
    async fn read_rtu(&mut self) -> TransportResult<Vec<u8>> {
        let mut out = Vec::with_capacity(64);
        let mut buf = [0u8; 256];
        loop {
            match tokio::time::timeout(Duration::from_millis(5), self.stream.read(&mut buf)).await {
                Ok(Ok(0)) => break,
                Ok(Ok(n)) => out.extend_from_slice(&buf[..n]),
                Ok(Err(e)) => return Err(TransportError::Io(e)),
                Err(_) => break, // silence = end of frame
            }
        }
        if out.is_empty() {
            Err(TransportError::Timeout(Duration::from_millis(5)))
        } else {
            Ok(out)
        }
    }
}

#[async_trait]
impl Transport for TcpTransport {
    fn name(&self) -> String {
        format!(
            "{}://{}:{} ({:?})",
            if self.config.tls.is_some() { "tcps" } else { "tcp" },
            self.config.host,
            self.config.port,
            self.config.framing
        )
    }

    async fn reset(&mut self) -> TransportResult<()> {
        Ok(()) // framing keeps stream boundaries; no stale data to discard
    }

    async fn close(&mut self) -> TransportResult<()> {
        let _ = self.stream.shutdown().await;
        Ok(())
    }

    async fn send_raw(&mut self, adu: &[u8]) -> TransportResult<()> {
        // The scanner builds the exact ADU (MBAP or RTU) including the
        // transaction id; the transport never rewrites it.
        self.stream.write_all(adu).await?;
        self.stream.flush().await?;
        Ok(())
    }

    async fn recv_raw(&mut self, _expected_hint: usize) -> TransportResult<Vec<u8>> {
        match self.config.framing {
            TcpFraming::Mbap => self.read_mbap().await,
            TcpFraming::Rtu => self.read_rtu().await,
        }
    }
}
